#include <vector>
#include <algorithm>

struct Interval { int start, end; };

std::vector<Interval> mergeIntervals(std::vector<Interval> iv) {
    if (iv.empty()) return {};
    std::sort(iv.begin(), iv.end(), [](auto& a, auto& b) { return a.start < b.start; });

    std::vector<Interval> out{iv[0]};
    for (size_t k = 1; k < iv.size(); k++) {
        if (iv[k].start > out.back().end) out.push_back(iv[k]);
        // max, not iv[k].end: it may be entirely inside the last one.
        else out.back().end = std::max(out.back().end, iv[k].end);
    }
    return out;
}

int minimumPlatforms(const std::vector<Interval>& iv) {
    std::vector<int> arr, dep;
    for (auto& x : iv) { arr.push_back(x.start); dep.push_back(x.end); }
    std::sort(arr.begin(), arr.end());
    std::sort(dep.begin(), dep.end());

    size_t i = 0, j = 0;
    int inUse = 0, peak = 0;
    while (i < arr.size()) {
        if (arr[i] <= dep[j]) { inUse++; peak = std::max(peak, inUse); i++; }
        else { inUse--; j++; }
    }
    return peak;
}
